#include "interpreter.h"

OCTAVE_BEGIN_NAMESPACE(octave)

void graphics_init (interpreter& interp)
{
  gh_manager& gh_mgr = interp.get_gh_manager ();

  autolock guard (gh_mgr.graphics_lock ());

  qRegisterMetaType<graphics_object> ("graphics_object");

  gh_mgr.enable_event_processing (true);

  qt_graphics_toolkit *qt_gtk = new qt_graphics_toolkit (interp);

  if (QThread::currentThread ()
      != QApplication::instance ()->thread ())
    qt_gtk->moveToThread (QApplication::instance ()->thread ());

  graphics_toolkit tk (qt_gtk);","lineStart":1,"lineEnd":60,"totalLines":69,"truncated":true}},"title":"repos/ruangong-0707/octave/liboctgui/src/graphics-init.cc","time":{"start":1783572569907,"end":1783572569916}},"id":"prt_f45359c7500189ryRoYA7T31MA","sessionID":"ses_0bacc1a02ffew4h0g77h5jdHVA","messageID":"msg_f45358e4d001xJTbIgkZBCftJ7"}}

